// Members of Store. All panel data stays in the local channel document.
bool hasStoryboard()const{for(auto& row:doc.at("channels"))if(str(row,"id")==active)return row.contains("storyboard");return false;}
std::string activePanelId(){return hasStoryboard()?str(current()["storyboard"],"active_panel"):"";}
void boardBackup(){snapshot();atomicWrite(root/"config/storyboard-backups"/(active+"-"+id()+".json"),current().dump(2));}
void enableStoryboard(){if(hasStoryboard())return;snapshot();auto board=initialStoryboard(state);validateStoryboard(board);boardBackup();current()["storyboard"]=board;restore();save();}
void disableStoryboard(){if(!hasStoryboard())return;boardBackup();current().erase("storyboard");state.erase("_story_context");save();}
void selectBoard(const std::string& page,const std::string& panel){snapshot();auto board=current().at("storyboard");boardPanel(board,page,panel);board["active_page"]=page;board["active_panel"]=panel;validateStoryboard(board);current()["storyboard"]=std::move(board);restore();save();}
void mutateBoard(const std::function<void(json&)>& change){if(!hasStoryboard())throw std::runtime_error("페이지·컷을 먼저 시작하세요.");snapshot();auto board=current()["storyboard"];change(board);validateStoryboard(board);current()["storyboard"]=std::move(board);restore();save();}
void addBoardPage(const std::string& name){mutateBoard([&](json& board){auto page=id(),panel=id();auto base=board["defaults"];board["pages"].push_back({{"id",page},{"name",name},{"defaults",base},{"panels",json::array({{{"id",panel},{"name","1컷"},{"snapshot",base},{"baseline",base},{"selected",nullptr}}})}});board["active_page"]=page;board["active_panel"]=panel;});}
void addBoardPanel(bool duplicate=false){mutateBoard([&](json& board){auto page=str(board,"active_page");auto& row=boardPage(board,page);auto snapshot=duplicate?activeBoardPanel(board)["snapshot"]:row["defaults"];auto key=id();row["panels"].push_back({{"id",key},{"name",std::to_string(row["panels"].size()+1)+"컷"},{"snapshot",snapshot},{"baseline",snapshot},{"selected",nullptr}});board["active_panel"]=key;});}
void renameBoard(bool page,const std::string& name){mutateBoard([&](json& board){(page?boardPage(board,str(board,"active_page")):activeBoardPanel(board))["name"]=name;});}
void boardDefaults(bool project){mutateBoard([&](json& board){auto value=activeBoardPanel(board)["snapshot"];if(project)board["defaults"]=value;else boardPage(board,str(board,"active_page"))["defaults"]=value;});}
void resetBoardPanel(bool undo=false){mutateBoard([&](json& board){auto& panel=activeBoardPanel(board);if(undo&&!panel.contains("previous"))throw std::runtime_error("복원 취소할 기록이 없습니다.");auto target=undo?panel["previous"]:panel["baseline"];panel["previous"]=panel["snapshot"];panel["snapshot"]=target;});}
void deleteBoard(bool page){mutateBoard([&](json& board){auto pageId=str(board,"active_page"),panelId=str(board,"active_panel");auto& pages=board["pages"];auto& parent=boardPage(board,pageId);auto& panels=parent["panels"];if(page&&pages.size()==1||!page&&panels.size()==1)throw std::runtime_error("마지막 페이지나 컷은 삭제할 수 없습니다.");auto& trash=board["trash"];if(!trash.is_array())trash=json::array();trash.push_back({{"kind",page?"page":"panel"},{"page",pageId},{"index",0},{"value",page?parent:activeBoardPanel(board)}});if(trash.size()>10)trash.erase(trash.begin());if(page){size_t index=0;for(;index<pages.size()&&str(pages[index],"id")!=pageId;index++);trash.back()["index"]=index;pages.erase(pages.begin()+index);board["active_page"]=str(pages[std::min(index,pages.size()-1)],"id");board["active_panel"]=str(boardPage(board,str(board,"active_page"))["panels"][0],"id");}else{size_t index=0;for(;index<panels.size()&&str(panels[index],"id")!=panelId;index++);trash.back()["index"]=index;panels.erase(panels.begin()+index);board["active_panel"]=str(panels[std::min(index,panels.size()-1)],"id");}});}
void undoBoardDelete(){mutateBoard([&](json& board){auto& trash=board["trash"];if(trash.empty())throw std::runtime_error("복원할 삭제 기록이 없습니다.");auto item=trash.back();trash.erase(trash.end()-1);auto& list=str(item,"kind")=="page"?board["pages"]:boardPage(board,str(item,"page"))["panels"];size_t index=std::min(item.value("index",size_t(0)),list.size());list.insert(list.begin()+index,item["value"]);board["active_page"]=str(item,"kind")=="page"?str(item["value"],"id"):str(item,"page");board["active_panel"]=str(item,"kind")=="page"?str(item["value"]["panels"][0],"id"):str(item["value"],"id");});}
void restoreStoryboardRecord(const json& record){if(str(record,"id")!=active||!record.contains("storyboard"))throw std::runtime_error("현재 프로젝트의 페이지·컷 백업을 선택하세요.");auto board=record["storyboard"];validateStoryboard(board);boardBackup();current()["storyboard"]=std::move(board);restore();save();}
